/* lineno==0 gives the most recent message (e.g.
   "Do you want to call panic..." if called from #panic) */
export function get_saved_pline(lineno) {
    let p = 0;
    let limit = 50;
    if (lineno >= 50) {
        return null;
    }
    p = (game.saved_pline_index - 1) % 50;
    while (limit--) {
        if (game.saved_plines[p]) {
            if (lineno--) {
                p = (p - 1 + 50) % 50;
            } else {
                return game.saved_plines[p];
            }
        }
    }
    return null;
}
